/* Output pixels per guest pixel along one axis of a scene-sized surface. */
static double ma2_hud_pixel_scale(int vertical,int32_t size)
{
    if(size<=0)return 1.0;
    unsigned pixel_width,pixel_height,width=vertical?640u:(unsigned)size,height=vertical?(unsigned)size:480u;
